export interface Page<T> {
  items: T[];
  page: number;
  perPage: number;
  totalItems: number;
  totalPages: number;
  hasPrev: boolean;
  hasNext: boolean;
}

/**
 * Splits `items` into pages for a list view.
 *
 * - `perPage` must be an integer of 1 or more. Anything else throws a
 *   RangeError.
 * - `totalPages` is the number of pages needed to show every item. An
 *   empty list still has 1 (empty) page.
 * - `page` is 1-based. It is rounded down to an integer first. NaN, or
 *   anything below 1, means page 1. Anything past the last page means
 *   the last page. The returned `page` is the page actually shown.
 * - `items` holds that page's items, in order. The input array is
 *   never modified.
 * - `hasPrev` is true when there is a page before this one, and
 *   `hasNext` is true when there is a page after it.
 */
export function paginate<T>(
  items: T[],
  page: number,
  perPage = 10,
): Page<T> {
  if (!Number.isInteger(perPage) || perPage < 1) {
    throw new RangeError("perPage must be an integer of 1 or more");
  }

  const totalItems = items.length;
  const totalPages = totalItems === 0 ? 1 : Math.ceil(totalItems / perPage);

  let current = Math.floor(page);
  if (Number.isNaN(current) || current < 1) {
    current = 1;
  }
  if (current > totalPages) {
    current = totalPages;
  }

  const start = (current - 1) * perPage;
  const pageItems = items.slice(start, start + perPage);

  return {
    items: pageItems,
    page: current,
    perPage,
    totalItems,
    totalPages,
    hasPrev: current > 1,
    hasNext: current < totalPages,
  };
}
```

**Fixes applied:**

| # | Bug | Root cause | Fix |
|---|-----|-----------|-----|
| 1 | 20 items / 10-per-page → 3 pages | `Math.floor(n/d)+1` overcounts when `n` is a multiple of `d` | Use `Math.ceil(totalItems / perPage)` (with `1` for the empty-list case) |
| 2 | 11 items, page 1 has no Next | `hasNext` compared against `totalItems - 1` (off-by-one) | `hasNext: current < totalPages` |
| 3 | Viewing a page "deletes" items | `items.splice(start, perPage)` **mutates** the caller's array | Use `items.slice(start, start + perPage)` |
| 4 | `?page=abc` shows blank list | `NaN < 1` is `false`, so `current` stayed `NaN` and `slice(NaN,…)` returned `[]` | After `Math.floor`, explicitly check `Number.isNaN(current)` and fall back to page 1 |

**Additional hardening:** the original code never validated `perPage`; the contract says a non-integer or value `< 1` must throw a `RangeError`, so that guard was added.

